const fields: string[] = [];
let field = "";
let inQuotes = false;
let isQuoted = false;

for (let index = 0; index < row.length; index += 1) {
  const character = row[index];

  if (inQuotes) {
    if (character === '"') {
      if (row[index + 1] === '"') {
        field += '"';
        index += 1;
      } else {
        inQuotes = false;
      }
    } else {
      field += character;
    }
  } else if (character === '"') {
    inQuotes = true;
    isQuoted = true;
  } else if (character === ",") {
    fields.push(isQuoted ? field : field.trim());
    field = "";
    isQuoted = false;
  } else {
    field += character;
  }
}

fields.push(isQuoted ? field : field.trim());
return fields;

