const values: string[] = [];
let index = 0;

while (index <= row.length) {
  let value = "";
  let cursor = index;

  while (cursor < row.length && /\s/.test(row[cursor])) {
    cursor += 1;
  }

  if (row[cursor] === '"') {
    index = cursor + 1;

    while (index < row.length) {
      if (row[index] === '"') {
        if (row[index + 1] === '"') {
          value += '"';
          index += 2;
        } else {
          index += 1;
          break;
        }
      } else {
        value += row[index];
        index += 1;
      }
    }

    while (index < row.length && row[index] !== ",") {
      index += 1;
    }
  } else {
    const start = index;
    while (index < row.length && row[index] !== ",") {
      index += 1;
    }
    value = row.slice(start, index).trim();
  }

  values.push(value);

  if (index === row.length) {
    break;
  }
  index += 1;
}

return values;

