      }
    } else {
      field += character;
    }
  } else if (character === ",") {
    pushField();
  } else if (character === '"' && field.trim() === "") {
    field = "";
    quoted = true;
    inQuotes = true;
  } else if (!afterQuote) {
    field += character;
  }
}

pushField();
return fields;
